"""Actual opening art, manager workstation and buy-after-edit persistence, isolated saves."""
import os,sys,json,http.server,threading,functools
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'artifacts/qa-python'))
from playwright.sync_api import sync_playwright
OUT=ROOT/'artifacts/office-space';OUT.mkdir(parents=True,exist_ok=True);report=[]
class Quiet(http.server.SimpleHTTPRequestHandler):
 def log_message(self,*a):pass
server=http.server.ThreadingHTTPServer(('127.0.0.1',8794),functools.partial(Quiet,directory=str(ROOT/'dist')));threading.Thread(target=server.serve_forever,daemon=True).start()
try:
 with sync_playwright() as p:
  browser=p.chromium.launch(headless=True,executable_path=os.environ.get('CHROMIUM_PATH') or ('C:/Program Files/Google/Chrome/Application/chrome.exe' if os.name=='nt' else None),args=['--disable-gpu-shader-disk-cache','--disk-cache-size=1'])
  for width,height in [(1366,768),(390,844)]:
   ctx=browser.new_context(viewport={'width':width,'height':height});page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
   def snap(name):page.screenshot(path=str(OUT/(name+'-'+str(width)+'.png')))
   def menu():
    if not page.locator('.living-more').evaluate('(e)=>e.open'):page.locator('.living-more summary').click()
   def resume():page.locator('.cinematic-resume').click();page.locator('.pm-root').wait_for();page.wait_for_function('(()=>{const f=PilhaLiving.getFurniture();return f&&f.loaded===f.assets;})()')
   try:
    page.goto('http://127.0.0.1:8794/');page.locator('.cinematic-start').click();page.locator('.pi-invite').wait_for(state='visible');page.wait_for_function('(()=>{const f=document.querySelector(".pi-root").getIntroFurnitureStatus();return f&&f.loaded===f.assets&&f.baseline>20;})()');intro=page.locator('.pi-root').evaluate('(e)=>e.getIntroFurnitureStatus()');snap('opening-approved-art')
    page.evaluate("""async()=>{const M=await import('/simulation/company-continuous.js'),L=await import('/simulation/company-living.js');let s=L.ensureLiving(M.fresh());s.budget=100000;s.team={principal:'PILHA-H01',support:'PILHA-H02'};s.paused=true;s.events.nextWeek=999;s.lastWallMs=Date.now();s=M.purchase(s,M.quote(s,'escritorio','cadeira-producao',{targetId:'NPC-01'})).state;localStorage.setItem(M.KEY,JSON.stringify(s));}""");page.reload();resume();original=page.evaluate('PilhaLiving.getState()');office=page.evaluate('PilhaLiving.getOfficeSpace()');assert len(office['manager'])==1;assert office['manager'][0]['workstation']['y']<0;assert len(office['partitions'])>=7;snap('company-extension')
    menu();page.locator('[data-company=manager-office]').click();page.wait_for_timeout(650);snap('manager-room')
    # Real keyboard editing of a baseline object, then a real purchase through the shop.
    menu();page.locator('[data-company=layout]').click();page.locator('.furniture-editor').wait_for();choice=page.evaluate("""async()=>{const {validatePlacement}=await import('/simulation/furniture-layout.js'),rows=PilhaLiving.getEditableFurniture(),room=PilhaLiving.getFurnitureLayout().find(r=>r.id==='escritorio'),items=room.items.map(i=>({...i,t:i.type,layoutHidden:i.hidden}));for(let i=0;i<rows.length;i++){const r=rows[i];if(r.sid!=='escritorio'||!r.key.startsWith('base:plant:'))continue;for(const [dx,dy] of [[.25,0],[-.25,0],[0,.25],[0,-.25]])if(validatePlacement({...items.find(b=>b.layoutKey===r.key),x:r.x+dx,y:r.y+dy},items,r.sid).ok)return {index:i,row:r,dx,dy};}throw Error('No valid move');}""");page.locator('[data-layout-select]').select_option(str(choice['index']));page.wait_for_timeout(350);page.locator('[data-layout-'+('dx' if choice['dx'] else 'dy')+'="'+str(choice['dx'] or choice['dy'])+'"]').click();assert 'Posição ajustada' in page.locator('.layout-status').inner_text();page.locator('[data-layout-save]').click();page.locator('.furniture-editor').wait_for(state='detached');saved=page.evaluate('PilhaLiving.getState().furnitureLayout');pose=saved['rooms']['escritorio'][choice['row']['key']]
    page.locator('.pm-tab[data-i="0"]').click();before=page.evaluate('PilhaLiving.getState()');cost=page.evaluate("async()=>{const M=await import('/simulation/company-continuous.js');return M.quote(PilhaLiving.getState(),'escritorio','asse').cost;}");page.locator('[data-act=buy][data-id=asse]').click();page.wait_for_function('PilhaLiving.getState().receipts.some(r=>r.sid==="escritorio"&&r.id==="asse"&&r.level===1)');page.wait_for_timeout(400);after=page.evaluate('PilhaLiving.getState()');assert after['budget']==before['budget']-cost;assert after['week']==before['week'] and after['staff']==before['staff'];current=page.evaluate('(key)=>PilhaLiving.getEditableFurniture().find(r=>r.key===key)',choice['row']['key']);assert current['x']==pose['x'] and current['y']==pose['y'];assert after['furnitureLayout']==saved;snap('after-purchase-kept-layout');page.reload();resume();current=page.evaluate('(key)=>PilhaLiving.getEditableFurniture().find(r=>r.key===key)',choice['row']['key']);assert current['x']==pose['x'] and current['y']==pose['y']
    page.locator('.pm-tab[data-i="3"]').click();page.locator('[data-act=buy][data-id=arvore]').click();page.wait_for_function('PilhaLiving.getState().receipts.some(r=>r.sid==="restauracao"&&r.id==="arvore"&&r.level===1)');assert page.evaluate('PilhaLiving.getFurnitureLayout().find(r=>r.id==="restauracao").items.some(i=>i.asset==="arvore-sombra"&&!i.hidden)');page.locator('[data-item=arvore]').evaluate('(e)=>e.scrollIntoView({behavior:"instant",block:"center"})');snap('tree-inventory');page.locator('[data-act=close]').click()
    # Observe the real work agenda until the existing manager occupies the new room.
    seated=page.evaluate("""async()=>{const M=await import('/simulation/company-continuous.js'),manager=PilhaLiving.getOfficeSpace().manager[0].id;for(let i=0;i<200;i++){const s=PilhaLiving.getState();s.activeMs=i*s.clockWeekMs/210;s.lastWallMs=Date.now();localStorage.setItem(M.KEY,JSON.stringify(s));await PilhaLiving.syncClock();const p=PilhaLiving.getEmployees().find(p=>p.id===manager);if(p?.activity==='computer'&&p.y<0)return p;}return null;}""");assert seated and seated['sitting'];menu();page.locator('[data-company=manager-office]').click();page.wait_for_timeout(650);snap('manager-at-computer');assert len(page.evaluate('PilhaLiving.getEmployees()'))==16;assert not errors,errors
    report.append({'viewport':[width,height],'openingFurniture':intro,'office':office,'savedAfterPurchaseAndReload':pose,'managerSeated':seated,'treePurchased':True,'errors':errors});ctx.close()
   except Exception:snap('FAILED');raise
  browser.close()
finally:server.shutdown();(OUT/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'viewports':len(report),'buyAfterEditPreserved':True,'managerWorkstation':True,'openingUsesApprovedArt':True,'treePurchased':True}))
